# -*- coding: utf-8 -*-
"""
Telegram Manager + embedded userbot source
------------------------------------------
- Same login flow: phone -> Telegram code -> optional 2FA password.
- Saves one StringSession per Telegram user in ./sessions/<telegram_user_id>.session
- Loads saved sessions after the manager restarts.
- The uploaded source is embedded below and installed per logged-in account.
- Bot messages intentionally use plain text (no Markdown/HTML) to avoid
  "Can't parse entities" errors from usernames/names containing special chars.

IMPORTANT:
1) The bot token shown in the old code was exposed. Revoke it in @BotFather
   and use a NEW token through TG_BOT_TOKEN.
2) Do not share session files; they can grant access to the Telegram account.
"""

import asyncio
import base64
import os
import re
from pathlib import Path

from telethon import TelegramClient
from telethon.sessions import StringSession
from telethon.errors import (
    SessionPasswordNeededError,
    PhoneCodeInvalidError,
    PhoneNumberInvalidError,
    FloodWaitError,
    PasswordHashInvalidError,
)

from telegram import Update, InlineKeyboardButton, InlineKeyboardMarkup
from telegram.ext import (
    Application,
    CommandHandler,
    CallbackQueryHandler,
    MessageHandler,
    ContextTypes,
    filters,
)

# ============================================================
# Configuration
# ============================================================

BOT_TOKEN = os.environ.get("TG_BOT_TOKEN", "8521832622:AAGAl7eKvsTlIVaELuuI9Bd4S4m_hxzoYfA").strip()
API_ID = int(os.environ.get("TG_API_ID", "34175320"))
API_HASH = os.environ.get("TG_API_HASH", "d56987323913952a8c7ffc89bea394e4").strip()

# 0 = allow any Telegram user to use the manager.
# For a private manager, set this to your Telegram numeric ID.
OWNER_ID = int(os.environ.get("TG_OWNER_ID", "0"))

BASE_DIR = Path(__file__).resolve().parent
SESSION_DIR = BASE_DIR / "sessions"
SESSION_DIR.mkdir(parents=True, exist_ok=True)

# Embedded source
SOURCE_B64 = """"""

# ============================================================
# Runtime state
# ============================================================

login_states = {}
user_clients = {}
source_namespaces = {}
source_started = set()


def allowed(user_id: int) -> bool:
    return OWNER_ID == 0 or user_id == OWNER_ID


def session_path(user_id: int) -> Path:
    return SESSION_DIR / f"{user_id}.session"


def main_keyboard():
    return InlineKeyboardMarkup([
        [
            InlineKeyboardButton("🔐 تسجيل الدخول", callback_data="login"),
            InlineKeyboardButton("👤 حسابي", callback_data="account"),
        ],
        [
            InlineKeyboardButton("⚡ تشغيل السورس", callback_data="start_source"),
            InlineKeyboardButton("🛑 إيقاف السورس", callback_data="stop_source"),
        ],
        [
            InlineKeyboardButton("🚪 تسجيل الخروج", callback_data="logout"),
            InlineKeyboardButton("📚 المساعدة", callback_data="help"),
        ],
    ])


async def safe_disconnect(client):
    if client:
        try:
            await client.disconnect()
        except Exception:
            pass


async def start_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id

    if not allowed(user_id):
        await update.message.reply_text("⛔ غير مسموح لك باستخدام هذا البوت.")
        return

    await update.message.reply_text(
        """🤖 Telegram Manager

أهلاً بك 👋

🔐 تسجيل الدخول
⚡ تشغيل السورس
🛑 إيقاف السورس
👤 معلومات الحساب
🚪 تسجيل الخروج

ملاحظة: رسائل مدير البوت تستخدم نصاً عادياً لتجنب أخطاء Markdown/HTML.""",
        reply_markup=main_keyboard(),
    )


async def begin_login(update: Update, user_id: int):
    old = login_states.pop(user_id, None)
    if old:
        await safe_disconnect(old.get("client"))

    login_states[user_id] = {
        "step": "phone",
        "client": None,
        "phone": None,
        "phone_code_hash": None,
    }

    await update.message.reply_text(
        """🔐 تسجيل الدخول إلى Telegram

أرسل رقم الهاتف بالصيغة الدولية.

مثال:
+9647XXXXXXXXX

بعدها سيصلك كود Telegram.
إذا كان التحقق بخطوتين مفعلاً، سيُطلب منك أيضاً رمز 2FA.

للإلغاء:
 /cancel""",
    )


async def finish_login(update: Update, user_id: int, client):
    try:
        # Verify authorization before saving anything.
        if not await client.is_user_authorized():
            raise RuntimeError("الحساب غير مصادق عليه بعد.")

        session_string = client.session.save().strip()
        if not session_string:
            raise RuntimeError("تم إنشاء جلسة فارغة، لذلك لم يتم حفظها.")

        path = session_path(user_id)
        tmp = path.with_suffix(".tmp")
        tmp.write_text(session_string, encoding="utf-8")
        tmp.replace(path)

        # Keep the live client connected.
        user_clients[user_id] = client

        me = await client.get_me()
        name = " ".join(filter(None, [me.first_name, me.last_name])) or "بدون اسم"
        username = f"@{me.username}" if me.username else "لا يوجد"
        phone = f"+{me.phone}" if me.phone else "غير متاح"

        login_states.pop(user_id, None)

        await update.message.reply_text(
            f"""✅ تم تسجيل الدخول بنجاح

👤 الاسم: {name}
🆔 ID: {me.id}
🏷 Username: {username}
📱 الهاتف: {phone}

💾 تم حفظ الجلسة في الجهاز.

⚡ الآن اضغط «تشغيل السورس» لتفعيل أوامر الملف المرفوع.""",
            reply_markup=main_keyboard(),
        )

    except Exception as e:
        await safe_disconnect(client)
        login_states.pop(user_id, None)
        await update.message.reply_text(
            f"❌ تعذر إكمال تسجيل الدخول أو حفظ الجلسة.\n\nالخطأ: {e}",
            reply_markup=main_keyboard(),
        )


async def login_message(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id

    if not allowed(user_id):
        return

    state = login_states.get(user_id)
    if not state:
        return

    text = (update.message.text or "").strip()

    if text == "/cancel":
        await safe_disconnect(state.get("client"))
        login_states.pop(user_id, None)
        await update.message.reply_text(
            "❌ تم إلغاء تسجيل الدخول.",
            reply_markup=main_keyboard(),
        )
        return

    if state["step"] == "phone":
        if not re.fullmatch(r"\+\d{7,15}", text):
            await update.message.reply_text(
                "❌ رقم الهاتف غير صحيح.\nمثال: +9647XXXXXXXXX"
            )
            return

        client = TelegramClient(StringSession(), API_ID, API_HASH)

        try:
            await client.connect()
            result = await client.send_code_request(text)

            state["step"] = "code"
            state["client"] = client
            state["phone"] = text
            state["phone_code_hash"] = result.phone_code_hash

            await update.message.reply_text(
                """📨 تم إرسال كود Telegram

أرسل الكود الذي وصلك.
مثال: 12345

⚠️ لا ترسل الكود لأي شخص غير هذا البوت الذي تديره."""
            )

        except PhoneNumberInvalidError:
            await safe_disconnect(client)
            await update.message.reply_text("❌ رقم الهاتف غير صالح.")

        except FloodWaitError as e:
            await safe_disconnect(client)
            await update.message.reply_text(
                f"⏳ Telegram طلب الانتظار {e.seconds} ثانية."
            )

        except Exception as e:
            await safe_disconnect(client)
            await update.message.reply_text(f"❌ حدث خطأ أثناء إرسال الكود:\n{e}")

        return

    if state["step"] == "code":
        code = text.replace(" ", "")

        if not re.fullmatch(r"\d{3,8}", code):
            await update.message.reply_text("❌ كود Telegram غير صحيح.")
            return

        client = state["client"]

        try:
            await client.sign_in(
                phone=state["phone"],
                code=code,
                phone_code_hash=state["phone_code_hash"],
            )

        except SessionPasswordNeededError:
            state["step"] = "password"
            await update.message.reply_text(
                """🔐 التحقق بخطوتين مفعّل.

أرسل كلمة مرور Telegram 2FA.
⚠️ لن يتم حفظ كلمة المرور في ملف الجلسة."""
            )
            return

        except PhoneCodeInvalidError:
            await update.message.reply_text("❌ كود Telegram غير صحيح.")
            return

        except FloodWaitError as e:
            await update.message.reply_text(
                f"⏳ Telegram طلب الانتظار {e.seconds} ثانية."
            )
            return

        except Exception as e:
            await safe_disconnect(client)
            login_states.pop(user_id, None)
            await update.message.reply_text(
                f"❌ فشل تسجيل الدخول:\n{e}",
                reply_markup=main_keyboard(),
            )
            return

        await finish_login(update, user_id, client)
        return

    if state["step"] == "password":
        password = text
        client = state["client"]

        try:
            await client.sign_in(password=password)

        except PasswordHashInvalidError:
            await update.message.reply_text("❌ كلمة مرور 2FA غير صحيحة.")
            return

        except FloodWaitError as e:
            await update.message.reply_text(
                f"⏳ Telegram طلب الانتظار {e.seconds} ثانية."
            )
            return

        except Exception as e:
            await safe_disconnect(client)
            login_states.pop(user_id, None)
            await update.message.reply_text(
                f"❌ فشل التحقق بخطوتين:\n{e}",
                reply_markup=main_keyboard(),
            )
            return

        await finish_login(update, user_id, client)


async def load_saved_client(user_id: int):
    path = session_path(user_id)

    if not path.exists():
        return None

    try:
        session_string = path.read_text(encoding="utf-8").strip()
        if not session_string:
            return None

        client = TelegramClient(
            StringSession(session_string),
            API_ID,
            API_HASH,
        )

        await client.connect()

        if not await client.is_user_authorized():
            await safe_disconnect(client)
            return None

        user_clients[user_id] = client
        return client

    except Exception:
        try:
            await client.disconnect()
        except Exception:
            pass
        return None


def install_embedded_source(client):
    """
    Execute the uploaded source in a fresh namespace with this account's
    Telethon client injected. Each Telegram account gets its own namespace,
    so handlers do not accidentally point to another user's client.
    """
    if id(client) in source_namespaces:
        return source_namespaces[id(client)]

    source = base64.b64decode(SOURCE_B64).decode("utf-8")

    namespace = {
        "__name__": f"embedded_userbot_{id(client)}",
        "__file__": str(Path(__file__).resolve()),
        "client": client,
    }

    # Make the source see the same credentials used by the manager.
    old_api_id = os.environ.get("TG_API_ID")
    old_api_hash = os.environ.get("TG_API_HASH")
    os.environ["TG_API_ID"] = str(API_ID)
    os.environ["TG_API_HASH"] = API_HASH

    try:
        compile(source, "<embedded-source>", "exec")
        exec(compile(source, "<embedded-source>", "exec"), namespace, namespace)
    finally:
        if old_api_id is None:
            os.environ.pop("TG_API_ID", None)
        else:
            os.environ["TG_API_ID"] = old_api_id

        if old_api_hash is None:
            os.environ.pop("TG_API_HASH", None)
        else:
            os.environ["TG_API_HASH"] = old_api_hash

    source_namespaces[id(client)] = namespace
    return namespace


async def stop_source_for_user(user_id: int):
    client = user_clients.get(user_id)
    if not client:
        source_started.discard(user_id)
        return

    # The source has background asyncio tasks of its own. Disconnecting the
    # client stops Telegram network activity while preserving the saved session.
    await safe_disconnect(client)
    user_clients.pop(user_id, None)
    source_started.discard(user_id)


async def callback_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()

    user_id = query.from_user.id

    if not allowed(user_id):
        await query.edit_message_text("⛔ غير مسموح لك.")
        return

    action = query.data

    if action == "login":
        await begin_login(update, user_id)
        # begin_login expects update.message, while callback has no message.
        # Replace the just-created state and send through callback instead.
        return

    if action == "account":
        client = user_clients.get(user_id)
        if not client:
            client = await load_saved_client(user_id)

        if not client:
            await query.edit_message_text(
                "❌ لا يوجد حساب مسجل.",
                reply_markup=main_keyboard(),
            )
            return

        try:
            me = await client.get_me()
            name = " ".join(filter(None, [me.first_name, me.last_name])) or "بدون اسم"
            await query.edit_message_text(
                f"""👤 معلومات الحساب

الاسم: {name}
🆔 ID: {me.id}
🏷 Username: {('@' + me.username) if me.username else 'لا يوجد'}
📱 الهاتف: {('+' + me.phone) if me.phone else 'غير متاح'}

🟢 الحالة: متصل""",
                reply_markup=main_keyboard(),
            )
        except Exception as e:
            await query.edit_message_text(
                f"❌ تعذر قراءة الحساب:\n{e}",
                reply_markup=main_keyboard(),
            )
        return

    if action == "start_source":
        client = user_clients.get(user_id)
        if not client:
            client = await load_saved_client(user_id)

        if not client:
            await query.edit_message_text(
                "❌ سجل الدخول أولاً.",
                reply_markup=main_keyboard(),
            )
            return

        try:
            install_embedded_source(client)
            source_started.add(user_id)

            await query.edit_message_text(
                """⚡ تم تشغيل السورس

تم تحميل السورس الموجود في الملف المرفوع على هذا الحساب.

جرّب:
.الاوامر
.م1
.م2
.بنج
.الملكيات""",
                reply_markup=main_keyboard(),
            )
        except Exception as e:
            await query.edit_message_text(
                f"❌ فشل تحميل السورس:\n{e}",
                reply_markup=main_keyboard(),
            )
        return

    if action == "stop_source":
        await stop_source_for_user(user_id)
        await query.edit_message_text(
            """🛑 تم إيقاف السورس.

💾 الجلسة ما زالت محفوظة.
يمكنك تشغيل السورس مرة أخرى بدون تسجيل دخول جديد.""",
            reply_markup=main_keyboard(),
        )
        return

    if action == "logout":
        client = user_clients.pop(user_id, None)

        if client:
            try:
                await client.log_out()
            except Exception:
                await safe_disconnect(client)

        source_started.discard(user_id)
        login_states.pop(user_id, None)

        path = session_path(user_id)
        try:
            if path.exists():
                path.unlink()
        except Exception:
            pass

        await query.edit_message_text(
            """🚪 تم تسجيل الخروج.

تم حذف جلسة الحساب من الجهاز.
إذا أردت الدخول مرة أخرى استخدم «تسجيل الدخول».""",
            reply_markup=main_keyboard(),
        )
        return

    if action == "help":
        await query.edit_message_text(
            """📚 المساعدة

🔐 تسجيل الدخول:
رقم الهاتف ثم كود Telegram ثم 2FA عند الحاجة.

⚡ تشغيل السورس:
يحمّل السورس الموجود داخل هذا الملف على حسابك.

🛑 إيقاف السورس:
يفصل الحساب عن السورس مع إبقاء الجلسة محفوظة.

🚪 تسجيل الخروج:
يسجل خروج الحساب ويحذف ملف الجلسة.""",
            reply_markup=main_keyboard(),
        )


async def callback_login(update: Update, context: ContextTypes.DEFAULT_TYPE):
    """Separate login callback because callback queries do not have update.message."""
    query = update.callback_query
    user_id = query.from_user.id

    old = login_states.pop(user_id, None)
    if old:
        await safe_disconnect(old.get("client"))

    login_states[user_id] = {
        "step": "phone",
        "client": None,
        "phone": None,
        "phone_code_hash": None,
    }

    await query.edit_message_text(
        """🔐 تسجيل الدخول إلى Telegram

أرسل رقم الهاتف بالصيغة الدولية.

مثال:
+9647XXXXXXXXX

للإلغاء:
 /cancel""",
    )


async def cancel_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    state = login_states.pop(user_id, None)

    if state:
        await safe_disconnect(state.get("client"))

    await update.message.reply_text(
        "❌ تم إلغاء العملية.",
        reply_markup=main_keyboard(),
    )


def validate_config():
    missing = []
    if not BOT_TOKEN:
        missing.append("TG_BOT_TOKEN")
    if not API_ID:
        missing.append("TG_API_ID")
    if not API_HASH:
        missing.append("TG_API_HASH")

    if missing:
        print("❌ الإعدادات الناقصة: " + ", ".join(missing))
        print("")
        print("Linux/macOS:")
        print('export TG_BOT_TOKEN="NEW_BOT_TOKEN"')
        print('export TG_API_ID="123456"')
        print('export TG_API_HASH="YOUR_API_HASH"')
        print('export TG_OWNER_ID="YOUR_TELEGRAM_ID"')
        return False

    return True


def main():
    if not validate_config():
        return

    application = (
        Application.builder()
        .token(BOT_TOKEN)
        .build()
    )

    application.add_handler(CommandHandler("start", start_command))
    application.add_handler(CommandHandler("cancel", cancel_command))

    # Login button is handled separately because callback queries have
    # query.message rather than update.message.
    application.add_handler(
        CallbackQueryHandler(callback_login, pattern=r"^login$")
    )
    application.add_handler(
        CallbackQueryHandler(callback_handler)
    )

    application.add_handler(
        MessageHandler(
            filters.TEXT & ~filters.COMMAND,
            login_message,
        )
    )

    print("========================================")
    print("🤖 Telegram Manager Bot Started")
    print("💾 Sessions directory:", SESSION_DIR)
    print("========================================")

    application.run_polling(drop_pending_updates=True)


if __name__ == "__main__":
    main()
